<?= $this->section('content') ?>
<div class="d-flex flex-wrap justify-content-between align-items-center gap-3 mb-4"><div><h1 class="h2 mb-1">Coletas</h1><p class="text-secondary mb-0">Endereços de coleta recebidos e aceitos pelo seu escopo.</p></div><a class="btn btn-outline-primary" href="<?= site_url('dashboard') ?>">Voltar aos pedidos</a></div>
<?php $pendingAcceptance = array_values(array_filter($orders, static fn (array $order): bool => $order['status'] === 'pending_acceptance')); $partnerForwarded = array_values(array_filter($orders, static fn (array $order): bool => $order['status'] === 'partner_forwarded')); ?>
<?php if ($pendingAcceptance !== []): ?><div class="alert alert-warning operational-alert" role="alert"><strong>Atenção:</strong> <?= count($pendingAcceptance) ?> pedido(s) aguardam aceite. Próximo prazo: <span data-countdown-deadline="<?= esc($pendingAcceptance[0]['acceptanceDeadlineAt'] ?? '') ?>">carregando...</span>.</div><?php endif ?>
<?php if ($partnerForwarded !== []): ?><div class="alert alert-danger" role="alert"><strong>Parceiro:</strong> <?= count($partnerForwarded) ?> pedido(s) foram reencaminhados por falta de aceite em 15 minutos.</div><?php endif ?>
<div class="card shadow-sm"><div class="card-body"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Contrato</th><th>Nome</th><th>Unidade</th><th>Endereço de coleta</th><th>Entregador</th><th>Atribuído em</th><th>Coleta confirmada</th><th>Status</th><th>Percurso</th></tr></thead><tbody>
<?php $pickupOrders = array_values(array_filter($orders, static fn (array $order): bool => in_array($order['status'], ['pending_acceptance', 'assigned', 'collected', 'in_transit', 'partner_forwarded'], true))); ?>
<?php if ($pickupOrders === []): ?><tr><td colspan="9" class="text-secondary">Nenhuma coleta disponível.</td></tr><?php else: foreach ($pickupOrders as $order): ?><tr><td class="fw-semibold"><?= esc($order['contract']) ?></td><td><?= esc($order['customerName']) ?></td><td><?= esc($order['unitId']) ?></td><td><?= esc($order['pickupAddress']) ?></td><td><?= $order['courierName'] !== null ? esc($order['courierName']) : '<span class="text-secondary">Ainda não atribuído</span>' ?></td><td><?= $order['assignedAt'] !== null ? esc(date('d/m/Y H:i', strtotime($order['assignedAt']))) : '—' ?></td><td><?= $order['collectionConfirmedAt'] !== null ? esc(date('d/m/Y H:i', strtotime($order['collectionConfirmedAt']))) : '—' ?></td><td><span class="badge text-bg-<?= $order['status'] === 'partner_forwarded' ? 'danger' : (in_array($order['status'], ['collected', 'in_transit'], true) ? 'primary' : ($order['status'] === 'pending_acceptance' ? 'warning' : 'info')) ?>"><?= esc(['pending_acceptance' => 'Aguardando aceite', 'partner_forwarded' => 'Parceiro', 'assigned' => 'Atribuído', 'collected' => 'Coletado', 'in_transit' => 'Em entrega'][$order['status']] ?? $order['status']) ?></span></td><td><?= $order['assignmentId'] !== null ? '<a class="btn btn-sm btn-outline-primary" href="' . esc(site_url('dashboard/routes?contract=' . rawurlencode($order['contract']))) . '">Ver percurso</a>' : '—' ?></td></tr><?php endforeach; endif ?>
</tbody></table></div></div></div>
